INSERT INTO `uni1_messages` VALUES
(4801,41,3,1794691365,50,'<span class=\"admin\">ADMIN Angigg</span>','<span class=\"admin\">RECORDATORIO PARA LA COMUNIDAD</span>','<span class=\"admin\">Muy pronto, el día 1, empieza nuestro Festival de Navidad, que será del 1 de diciembre hasta el 31 de diciembre.\n\nTendremos varias sorpresas y eventos en nuestro Xnova AstroIO.\n\nLos nuevos jugadores tendrán la posibilidad de emparejarse un poco con los jugadores que llevan tiempo jugando.\n\n¡No se lo pierdan! Gracias por su apoyo.\n\nLa Administración</span>',1,1,NULL,NULL),
